// Writes src/lib/leaflet-assets.ts from the installed `leaflet` package, so the map
// WebView runs Leaflet from the app bundle instead of a CDN (DRRM routing plan R6: offline
// rendering makes no requests to map or script CDNs). Rerun after changing the leaflet version;
// tests/leaflet-assets.test.ts fails while the generated file and the package differ.
import assert from 'node:assert/strict';
import { Buffer } from 'node:buffer';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const appRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(resolve(appRoot, 'package.json'));
const leafletRoot = dirname(require.resolve('leaflet/package.json'));
const { version } = JSON.parse(await readFile(resolve(leafletRoot, 'package.json'), 'utf8'));
const js = await readFile(resolve(leafletRoot, 'dist/leaflet.js'), 'utf8');
const css = await readFile(resolve(leafletRoot, 'dist/leaflet.css'), 'utf8');
const license = await readFile(resolve(leafletRoot, 'LICENSE'), 'utf8');

// Inlined into <script>/<style> elements and an HTML comment: these sequences would end them early.
assert.ok(!/<\/script/i.test(js), 'leaflet.js contains </script');
assert.ok(!/<\/style/i.test(css), 'leaflet.css contains </style');
assert.ok(!license.includes('--'), 'LICENSE contains --');

const sha256 = text => createHash('sha256').update(text, 'utf8').digest('hex');
const output = `// Generated by scripts/generate-leaflet-assets.mjs from leaflet@${version}. Do not edit.
// Leaflet is BSD-2-Clause licensed; LEAFLET_LICENSE is embedded in every map page.
// leaflet.js sha256 ${sha256(js)}
// leaflet.css sha256 ${sha256(css)}

export const LEAFLET_VERSION = ${JSON.stringify(version)};
export const LEAFLET_LICENSE = ${JSON.stringify(license)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
export const LEAFLET_JS = ${JSON.stringify(js)};
`;
await writeFile(resolve(appRoot, 'src/lib/leaflet-assets.ts'), output);
console.log(`Wrote src/lib/leaflet-assets.ts (leaflet@${version}, ${Buffer.byteLength(output)} bytes)`);
